INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dian','滇','["滇","滇国"]',NULL,'cn','east_asia',-279,1,NULL,'year',-109,1,NULL,'year',-3336,-1296,'ochre',NULL,NULL,'楚将庄蹻入滇称王；武帝元封二年（前109）尝羌降汉，设益州郡。庄蹻与尝羌之间世系失考。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yelang','夜郎','["夜郎","夜郎国"]',NULL,'cn','east_asia',-300,1,NULL,'year',-27,1,NULL,'year',-3588,-312,'ochre',NULL,NULL,'战国时已有夜郎；汉武帝时夜郎侯多同，末王兴前27年被诛。君主在位年多失考，不强行拉满王朝跨度。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dian-changqiang','尝羌','dian','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','尝羌是滇王，汉武帝元封二年（前109）率众归汉，汉廷在其地设置益州郡。此后滇王保留一定地方权力，直至西汉后期滇国王统终止。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滇国"},{"label":"《史记·西南夷列传》（维基文库）","url":"https://zh.wikisource.org/zh-hans/史記/卷116"},{"label":"《华阳国志·南中志》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=588599&if=gb&remap=gb"}]',NULL,NULL,'滇王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelang-duotong','多同','yelang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','夜郎侯，汉武帝遣唐蒙通夜郎时在位；《史记》载其国为西南夷最大。在位起讫无通行记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夜郎"}]',NULL,NULL,'夜郎侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelang-xin','兴','yelang','[]',NULL,NULL,NULL,NULL,NULL,NULL,-27,1,NULL,'year','["君主"]','夜郎王兴拒绝汉使陈立的招谕，前27年被陈立袭杀；夜郎由此并入汉朝郡县。此事见于《汉书·西南夷两粤朝鲜传》，后世“夜郎自大”典故则另有演变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夜郎"},{"label":"《汉书·西南夷两粤朝鲜传》（维基文库）","url":"https://zh.wikisource.org/zh-hans/漢書/卷095"},{"label":"《后汉书·南蛮西南夷列传》（维基文库）","url":"https://zh.wikisource.org/wiki/後漢書/卷86"},{"label":"《华阳国志·南中志》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=588599&if=gb&remap=gb"}]',NULL,NULL,'夜郎王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuang-qiao','庄蹻','dian','[]',NULL,NULL,NULL,NULL,NULL,NULL,-256,1,NULL,'year','["君主"]','庄蹻原为楚将，奉楚威王命经营黔中以西。秦军截断归路后，他留在滇地自立为王；其经历见于《史记·西南夷列传》，是滇国早期王统叙事的一部分。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/庄蹻"},{"label":"《史记·西南夷列传》（维基文库）","url":"https://zh.wikisource.org/zh-hans/史記/卷116"},{"label":"《华阳国志·南中志》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=588599&if=gb&remap=gb"}]',NULL,NULL,'滇王','[]');
